mapper.select:
SELECT review_reply_id, review_id, fair_id, admin_user_id, content, created_at, updated_at
  FROM fair_review_replies
 WHERE review_id = #{reviewId}

mapper.update:
UPDATE fair_review_replies
   SET content = #{content},
       updated_at = #{updatedAt}
 WHERE review_reply_id = #{reviewReplyId}
